import os
# find python processes whose cmdline contains server.py
for pid in filter(str.isdigit, os.listdir('/proc')):
    try:
        with open(f'/proc/{pid}/cmdline','rb') as f:
            cmd = f.read().replace(b'\0', b' ').decode().strip()
        if 'server.py' in cmd and 'python' in cmd:
            print(f'PID {pid}: {cmd}')
    except Exception:
